const fieldMatches = (expression, value, minimum, maximum) => expression.split(',').some((part) => {
  const [range, stepText = '1'] = part.split('/');
  const step = Number(stepText);
  let start = minimum;
  let end = maximum;
  if (range !== '*') {
    const bounds = range.split('-').map(Number);
    start = bounds[0];
    end = bounds.length === 2 ? bounds[1] : bounds[0];
  }
  return value >= start && value <= end && (value - start) % step === 0;
});
const cronMatchesNow = (cron, timezone) => {
  const fields = String(cron).trim().split(/\s+/);
  if (fields.length !== 5) return false;
  const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', {timeZone: timezone, minute:'2-digit', hour:'2-digit', hourCycle:'h23', day:'2-digit', month:'2-digit', weekday:'short'}).formatToParts(new Date()).map(({type,value}) => [type,value]));
  const minute = Number(parts.minute);
  const hour = Number(parts.hour);
  const day = Number(parts.day);
  const month = Number(parts.month);
  const weekday = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(parts.weekday);
  const dayOfMonthMatches = fieldMatches(fields[2], day, 1, 31);
  const dayOfWeekMatches = fieldMatches(fields[4], weekday, 0, 7) || (weekday === 0 && fieldMatches(fields[4], 7, 0, 7));
  const dayMatches = fields[2] !== '*' && fields[4] !== '*' ? dayOfMonthMatches || dayOfWeekMatches : dayOfMonthMatches && dayOfWeekMatches;
  return fieldMatches(fields[0], minute, 0, 59) && fieldMatches(fields[1], hour, 0, 23) && dayMatches && fieldMatches(fields[3], month, 1, 12);
};
return items.filter(({json}) => {
  const enabled = json.enabled === true || String(json.enabled).toLowerCase() === 'true';
  return enabled && cronMatchesNow(json.schedule_cron, json.timezone || 'UTC');
});
